'use client'

import { useEffect, useRef, useState } from 'react'

// Phases: 'show' while visible, 'out' during the fade, 'done' = unmounted.
// We start at 'show' so the overlay is part of the server-rendered HTML and
// paints on the very first frame — covering the page so the consumer screen
// never flashes underneath. The blocking script in layout.tsx decides whether
// this load should actually play (first open) or be skipped (already shown this
// session) via the `splash-skip` class on <html>; on skip, CSS hides the
// overlay before paint and the effect below unmounts it.
type Phase = 'show' | 'out' | 'done'

// The branded intro video (public/splash-intro.mp4) is a 5s portrait (9:16)
// clip that already contains the logo, "Go Grameen / Your Family Farmer" and
// the quote. It replaces the old CSS logo animation. Muted + playsInline so
// mobile browsers autoplay it. On a portrait phone it fills the screen; on a
// wide screen it sits centred over the brand-green background (object-contain,
// so the quote text is never cropped).
const INTRO_DURATION_MS = 5000

export default function SplashScreen() {
  const [phase, setPhase] = useState<Phase>('show')
  const timers = useRef<ReturnType<typeof setTimeout>[]>([])

  const clearTimers = () => {
    timers.current.forEach(clearTimeout)
    timers.current = []
  }

  // Fade the overlay out, then unmount it 0.5s later (matches the CSS fade).
  const startFadeOut = () => {
    clearTimers()
    setPhase('out')
    timers.current.push(setTimeout(() => setPhase('done'), 500))
  }

  useEffect(() => {
    // The pre-paint script in layout.tsx already wrote the sessionStorage flag
    // and tagged <html> when the splash had played before this session.
    const alreadyShown = document.documentElement.classList.contains('splash-skip')

    if (alreadyShown) {
      setPhase('done')
      return
    }

    // Fallback timers in case the video's `ended` event never fires (autoplay
    // blocked, decode error, etc.): fade out at 5s, unmount at 5.5s.
    timers.current.push(setTimeout(() => setPhase('out'), INTRO_DURATION_MS))
    timers.current.push(setTimeout(() => setPhase('done'), INTRO_DURATION_MS + 500))

    return clearTimers
  }, [])

  // Tapping anywhere during the splash skips it immediately.
  const skip = () => {
    clearTimers()
    setPhase('done')
  }

  if (phase === 'done') return null

  return (
    <div
      onClick={skip}
      role="presentation"
      aria-hidden
      className={`splash-overlay fixed inset-0 z-[200] flex items-center justify-center select-none ${
        phase === 'out' ? 'is-out' : ''
      }`}
      style={{ backgroundColor: '#1a5c2a' }}
    >
      <video
        className="w-full h-full object-contain"
        src="/splash-intro.mp4"
        autoPlay
        muted
        playsInline
        // Once the 5s clip finishes, fade the splash out instead of freezing on
        // the last frame.
        onEnded={startFadeOut}
        preload="auto"
      />
    </div>
  )
}

